// 历史免责只测具名保守证明边界；手写Task夹具不冒原任务实玩或遗产整World交割。
#include "resident/domains/tasks/task_inheritance_history.hpp"
#include "resident/domains/tasks/static_assets/task_static_asset.hpp"
#include <stdexcept>
#include <iostream>
using namespace hanmo::resident;
void need(bool ok,const char* why){if(!ok)throw std::runtime_error(why);}
// 合成来源只检窄历史边界；完整Task2支付/实交验证由原World先行，不能把此夹具称自然交割。
void closed_static_history_gates(){
    CommonState state;state.identity.tick=10;state.next_instance_id=20;ActorRecord dead;dead.id="dead";dead.alive=false;dead.available=false;dead.inventory_id="bag:dead";state.actors.insert(dead.id,dead);CommonStore c(state,std::make_shared<CommonCatalog>());TaskState tasks;TaskCatalog catalog;TaskDefinition d;d.id="offer";d.template_id="escort";d.issuer={Owner::Kind::actor,"sender",{}};d.goal.actor_id="protected";catalog.offers.insert(d.id,d);
    TaskRecord t;t.id="task:5";t.offer_id=d.id;t.assignee="dead";t.status="failed";t.accepted_tick=1;t.deadline_tick=4;t.reported_tick=2;t.settlement_id="settlement:9";t.budget_wallet_id="escrow";tasks.tasks.insert(t.id,t);WalletView escrow;escrow.id="escrow";escrow.owner={Owner::Kind::task,t.id,{}};c.state().wallets.insert(escrow.id,escrow);tasks.takeover_execution.emplace();tasks.takeover_execution->version=2;TaskStaticPaymentSource a;a.fact_id="task_static_payment:6";a.task_id=t.id;a.stage=TaskStaticPaymentStage::acceptance;a.tick=1;TaskStaticPaymentSource z;z.fact_id="task_static_payment:8";z.task_id=t.id;z.stage=TaskStaticPaymentStage::report_failure;z.tick=2;tasks.takeover_execution->static_payments.insert(a.fact_id,a);tasks.takeover_execution->static_payments.insert(z.fact_id,z);
    auto heads=[&](bool message){c.state().facts={};c.state().facts.insert(a.fact_id,{a.fact_id,"task_static_payment","tasks",{}});if(message)c.state().facts.insert("task_message_handoff:7",{"task_message_handoff:7","task_message_handoff","tasks",{}});c.state().facts.insert(z.fact_id,{z.fact_id,"task_static_payment","tasks",{}});c.state().facts.insert("family_inheritance:10",{"family_inheritance:10","family_inheritance_settled","family_inheritance",{}});};heads(false);
    const auto now=[&](){return validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok;};const auto before=[&](){return validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10).ok;};
    need(now()&&before(),"explicit completed escort cash source is provable both before and after inheritance");tasks.takeover_execution->version=1;need(!now()&&!before(),"old Task1 terminal status never supplies Task2 cash history");tasks.takeover_execution->version=2;c.state().wallets.find("escrow")->balance=1;need(!now()&&!before(),"remaining escrow blocks personal inheritance");c.state().wallets.find("escrow")->balance=0;
    c.state().facts.erase(z.fact_id);c.state().facts.insert(z.fact_id,{z.fact_id,"task_static_payment","tasks",{}});need(!before(),"same tick payment after inheritance cannot backfill earlier closure");heads(false);tasks.tasks.find(t.id)->settlement_id="settlement:11";need(!before(),"settlement completed after inheritance is unavailable");tasks.tasks.find(t.id)->settlement_id=t.settlement_id;
    InventoryView bag;bag.id="other.bag";bag.owner={Owner::Kind::actor,"other",{}};LotView lot;lot.id="lot:4";lot.item_id="cargo";lot.quantity=1;lot.owner={Owner::Kind::task,t.id,{}};bag.lots.push_back(lot);c.state().inventories.insert(bag.id,bag);need(!now()&&!before(),"Task custody in another person's container still blocks closure");c.state().inventories.erase(bag.id);
    catalog.offers.find(d.id)->template_id="procurement";need(!now()&&!before(),"procurement current empty cargo cannot supply missing historical transfer fact");catalog.offers.find(d.id)->template_id="message";catalog.offers.find(d.id)->goal.message_id="letter";catalog.offers.find(d.id)->goal.receiver_actor="recipient";tasks.tasks.find(t.id)->status="success";tasks.takeover_execution->static_payments.find(z.fact_id)->stage=TaskStaticPaymentStage::report_success;need(!now()&&!before(),"message needs independent original delivery proof");tasks.message_handoffs.emplace();TaskMessageHandoff handoff;handoff.fact_id="task_message_handoff:7";handoff.task_id=t.id;handoff.carrier_actor_id=t.assignee;handoff.recipient_actor_id="recipient";handoff.item_id="letter";handoff.tick=2;tasks.message_handoffs->receipts.insert(handoff.fact_id,handoff);heads(true);need(now()&&before(),"actual typed delivery precedes original report cash and inheritance");c.state().facts.erase(handoff.fact_id);c.state().facts.insert(handoff.fact_id,{handoff.fact_id,"task_message_handoff","tasks",{}});need(!now()&&!before(),"later physical handoff cannot backfill earlier report or inheritance");heads(true);tasks.tasks.find(t.id)->status="cancelled";tasks.tasks.find(t.id)->reported_tick.reset();tasks.takeover_execution->static_payments.find(z.fact_id)->stage=TaskStaticPaymentStage::cancellation;need(!now()&&!before(),"cancelled letter has no proven original return transfer and stays unavailable");
}

// 合成来源只核两种历史口同标尺；实际资源转移另由task_static_asset_test的原Common门覆盖。
void static_asset_history_gates(){
    CommonState seed;seed.identity.tick=10;seed.next_instance_id=50;ActorRecord actor;actor.id="dead";actor.alive=false;actor.inventory_id="bag:dead";seed.actors.insert(actor.id,actor);CommonStore c(seed,std::make_shared<CommonCatalog>());TaskState tasks;TaskCatalog catalog;TaskDefinition d;d.id="offer";d.template_id="procurement";d.issuer={Owner::Kind::actor,"issuer",{}};catalog.offers.insert(d.id,d);TaskRecord task;task.id="task:5";task.offer_id=d.id;task.assignee=actor.id;task.status="cancelled";task.accepted_tick=1;task.deadline_tick=20;task.settlement_id="settlement:10";task.budget_wallet_id="escrow";tasks.tasks.insert(task.id,task);c.state().wallets.insert("escrow",{"escrow",{Owner::Kind::task,task.id,{}},0,{}});
    tasks.takeover_execution.emplace();tasks.takeover_execution->version=2;TaskStaticPaymentSource accept;accept.fact_id="task_static_payment:6";accept.task_id=task.id;accept.tick=1;accept.stage=TaskStaticPaymentStage::acceptance;TaskStaticPaymentSource paid;paid.fact_id="task_static_payment:8";paid.task_id=task.id;paid.tick=2;paid.stage=TaskStaticPaymentStage::cancellation;tasks.takeover_execution->static_payments.insert(accept.fact_id,accept);tasks.takeover_execution->static_payments.insert(paid.fact_id,paid);tasks.static_assets.emplace();TaskStaticAssetReceipt assets;assets.fact_id="task_static_asset_transfer:9";assets.task_id=task.id;assets.stage="cancellation_return";assets.tick=2;tasks.static_assets->receipts.insert(assets.fact_id,assets);
    const auto heads=[&](){c.state().facts={};c.state().facts.insert(accept.fact_id,{accept.fact_id,"task_static_payment","tasks",{}});c.state().facts.insert(paid.fact_id,{paid.fact_id,"task_static_payment","tasks",{}});c.state().facts.insert(assets.fact_id,{assets.fact_id,task_static_asset_fact_kind,"tasks",{}});c.state().facts.insert("family_inheritance:11",{"family_inheritance:11","family_inheritance_settled","family_inheritance",{}});};heads();
    const auto now=[&](){return validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok;};const auto before=[&](){return validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:11",10).ok;};
    need(now()&&before(),"original cash plus zero retained actual cargo source supports both inheritance reads");need(validate_task_static_asset_cash_sources(c,tasks,*tasks.static_assets).ok,"same original cancellation cash confirms permanent transfer tick");tasks.static_assets->receipts.find(assets.fact_id)->tick=3;need(!now()&&!before()&&!validate_task_static_asset_cash_sources(c,tasks,*tasks.static_assets).ok,"single edited cancellation tick cannot borrow unchanged permanent payment");tasks.static_assets->receipts.find(assets.fact_id)->tick=2;tasks.static_assets->receipts.find(assets.fact_id)->retained_task_goods.push_back({"bag:dead","lot:7","grain",{},1});need(!now()&&!before(),"later current empty bag cannot backfill earlier retained Task goods");tasks.static_assets->receipts.find(assets.fact_id)->retained_task_goods.clear();c.state().facts.erase(assets.fact_id);c.state().facts.insert(assets.fact_id,{assets.fact_id,task_static_asset_fact_kind,"tasks",{}});need(!before(),"same tick asset fact after inheritance rejected");heads();c.state().facts.erase(paid.fact_id);c.state().facts.insert(paid.fact_id,{paid.fact_id,"task_static_payment","tasks",{}});need(!now()&&!before()&&!validate_task_static_asset_cash_sources(c,tasks,*tasks.static_assets).ok,"same tick receipt cannot precede its own original cash source");heads();catalog.offers.find(d.id)->template_id="message";need(now()&&before(),"original cancelled message return uses the same permanent source boundary");tasks.takeover_execution.reset();need(!now()&&!before(),"independent cargo profile never replaces missing Task2 financial closure");
}

int main(){try{closed_static_history_gates();static_asset_history_gates();CommonState state;state.identity.tick=10;state.next_instance_id=20;ActorRecord deceased;deceased.id="dead";deceased.alive=false;deceased.available=false;deceased.inventory_id="bag:dead";state.actors.insert("dead",deceased);CommonStore c(state,std::make_shared<CommonCatalog>());TaskState tasks;TaskCatalog catalog;need(validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok,"empty historical tasks provable now");c.state().facts.insert("family_inheritance:10",{"family_inheritance:10","family_inheritance_settled","family_inheritance",{}});need(validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10).ok,"same absence after exact inheritance fact");need(!validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",11).ok,"future fact tick denied");need(!validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","unknown:10",10).ok,"arbitrary header denied");TaskDefinition definition;definition.id="letter";definition.template_id="message";definition.issuer={Owner::Kind::actor,"sender",{}};definition.goal.receiver_actor="receiver";catalog.offers.insert("letter",definition);TaskRecord task;task.id="task:5";task.offer_id="letter";task.assignee="dead";task.status="success";tasks.tasks.insert(task.id,task);need(!validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok&&!validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10).ok,"settled task cannot be historical waiver");tasks.tasks.find(task.id)->assignee="carrier";need(validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok,"provably unrelated private parties remain eligible");catalog.offers.find("letter")->issuer={Owner::Kind::organization,"office",{}};catalog.offers.find("letter")->funding_wallet="public";need(!validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok,"public principal requires actual public wallet");WalletView public_wallet;public_wallet.id="public";public_wallet.owner={Owner::Kind::organization,"office",{}};c.state().wallets.insert("public",public_wallet);need(validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok&&validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10).ok,"unrelated public principal is not former official private debt");c.state().wallets.find("public")->owner={Owner::Kind::actor,"dead",{}};need(!validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok,"private wallet cannot impersonate public principal");c.state().wallets.find("public")->owner={Owner::Kind::organization,"office",{}};tasks.tasks.find(task.id)->assignee="dead";need(!validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok,"public task executor still has personal responsibility");tasks.tasks.erase("task:5");task.id="task:15";task.assignee="dead";tasks.tasks.insert(task.id,task);need(!validate_task_inheritance_history_provable_now(c,tasks,catalog,"dead").ok&&validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10).ok,"later related task does not rewrite prior inheritance absence");const auto before=encode_common_state(c.state());validate_task_inheritance_history_before_fact(c,tasks,catalog,"dead","family_inheritance:10",10);need(compare_boundary(before,encode_common_state(c.state())).exact(),"pure historical responsibility read");std::cout<<"Task inheritance history necessary conservative gates passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
